package com.combatxptracker;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlayerTaskMatcherTest
{
	@Test
	public void pluralTaskMatchesSingularNpc()
	{
		assertTrue(SlayerTaskMatcher.matches("Abyssal demons", "Abyssal demon"));
		assertTrue(SlayerTaskMatcher.matches("Black dragons", "Black dragon"));
		assertTrue(SlayerTaskMatcher.matches("Wolves", "Wolf"));
		assertTrue(SlayerTaskMatcher.matches("Harpie bug swarms", "Harpie bug swarm"));
		assertTrue(SlayerTaskMatcher.matches("Hellhounds", "Hellhound"));
	}

	@Test
	public void variantNamesStillMatch()
	{
		assertTrue(SlayerTaskMatcher.matches("Abyssal demons", "Greater abyssal demon"));
		assertTrue(SlayerTaskMatcher.matches("Greater demons", "Greater demon"));
		assertTrue(SlayerTaskMatcher.matches("Kalphite", "Kalphite Soldier"));
		assertTrue(SlayerTaskMatcher.matches("Zulrah", "Zulrah"));
	}

	@Test
	public void ignoresCaseTagsAndNonBreakingSpaces()
	{
		assertTrue(SlayerTaskMatcher.matches("ABYSSAL DEMONS", "<col=ffff00>Abyssal demon</col>"));
	}

	@Test
	public void differentMonstersDontMatch()
	{
		assertFalse(SlayerTaskMatcher.matches("Black demons", "Greater demon"));
		assertFalse(SlayerTaskMatcher.matches("Black dragons", "Blue dragon"));
		// Whole words only: "Rat" is not part of "Pirate".
		assertFalse(SlayerTaskMatcher.matches("Rats", "Pirate"));
	}

	@Test
	public void noTaskOrTargetNeverMatches()
	{
		assertFalse(SlayerTaskMatcher.matches(null, "Abyssal demon"));
		assertFalse(SlayerTaskMatcher.matches("Abyssal demons", null));
		assertFalse(SlayerTaskMatcher.matches("  ", "Abyssal demon"));
	}
}

package com.combatxptracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;
import org.junit.Test;

public class GoalTest
{
	@Test
	public void wholeNumbersUpTo126AreLevels()
	{
		Goal g = Goal.parse("99");
		assertEquals(Goal.Type.LEVEL, g.getType());
		assertEquals(99, g.getTargetLevel());
		assertEquals(13_034_431, g.getTargetXp());

		assertEquals(188_884_740, Goal.parse("126").getTargetXp());
		assertEquals(90, Goal.parse("lvl 90").getTargetLevel());
		assertEquals(2, Goal.parse("level 2").getTargetLevel());
	}

	@Test
	public void largerNumbersAreXp()
	{
		Goal g = Goal.parse("13,034,431");
		assertEquals(Goal.Type.XP, g.getType());
		assertEquals(13_034_431, g.getTargetXp());
		assertEquals(99, g.getTargetLevel());

		assertEquals(500, Goal.parse("500").getTargetXp());
	}

	@Test
	public void suffixesAreXp()
	{
		assertEquals(200_000_000, Goal.parse("200m").getTargetXp());
		assertEquals(200_000_000, Goal.parse("200M xp").getTargetXp());
		assertEquals(13_030_000, Goal.parse("13.03m").getTargetXp());
		assertEquals(500_000, Goal.parse("500k").getTargetXp());
		assertEquals(Goal.Type.XP, Goal.parse("50k").getType());
		// 200M is past level 126's XP, so it's shown as level 126.
		assertEquals(126, Goal.parse("200m").getTargetLevel());
	}

	@Test
	public void rejectsInvalidInput()
	{
		for (String bad : new String[]{"", "   ", "abc", "1", "0", "-5", "99.5", "201m", "1b", "nan", "12x"})
		{
			try
			{
				Goal.parse(bad);
				fail("Expected '" + bad + "' to be rejected");
			}
			catch (IllegalArgumentException expected)
			{
				// ok
			}
		}
	}

	@Test
	public void serializeRoundTrips()
	{
		for (String input : new String[]{"99", "126", "2", "200m", "13034431", "500k"})
		{
			Goal g = Goal.parse(input);
			assertEquals(g, Goal.deserialize(g.serialize()));
		}
	}

	@Test
	public void levelGoalsKeepTheOldSavedFormat()
	{
		// 1.3.x saved a bare level number. It must still load after updating.
		assertEquals("99", Goal.ofLevel(99).serialize());
		assertEquals(Goal.ofLevel(80), Goal.deserialize("80"));
	}

	@Test
	public void corruptSavedValuesAreIgnored()
	{
		assertNull(Goal.deserialize(null));
		assertNull(Goal.deserialize(""));
		assertNull(Goal.deserialize("banana"));
		assertNull(Goal.deserialize("xp:notanumber"));
		assertNull(Goal.deserialize("xp:999999999"));
	}

	@Test
	public void shortLabels()
	{
		assertEquals("99", Goal.parse("99").getShortLabel());
		assertEquals("200M", Goal.parse("200m").getShortLabel());
		assertEquals("13.03M", Goal.parse("13.03m").getShortLabel());
	}
}

package com.combatxptracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class MonsterTrackerTest
{
	@Test
	public void hitsAverageAndBiggestPerStyle()
	{
		MonsterTracker t = new MonsterTracker();
		t.recordHit("Abyssal demon", 20, CombatStyle.MELEE, 1);
		t.recordHit("Abyssal demon", 45, CombatStyle.MELEE, 2);
		t.recordHit("Abyssal demon", 38, CombatStyle.MAGIC, 3);
		t.recordHit("Abyssal demon", 0, CombatStyle.RANGED, 4);

		MonsterTracker.Snapshot s = t.snapshot().get(0);
		assertEquals(4, s.getHits());
		assertEquals((20 + 45 + 38 + 0) / 4.0, s.getAverageHit(), 1e-9);
		assertEquals(45, s.getBiggestHit());
		assertEquals(CombatStyle.MELEE, s.getBiggestHitStyle());
		assertEquals(Integer.valueOf(45), s.getBiggestByStyle().get(CombatStyle.MELEE));
		assertEquals(Integer.valueOf(38), s.getBiggestByStyle().get(CombatStyle.MAGIC));
		assertEquals(Integer.valueOf(0), s.getBiggestByStyle().get(CombatStyle.RANGED));
	}

	@Test
	public void unknownStyleStillCountsTowardTotals()
	{
		MonsterTracker t = new MonsterTracker();
		t.recordHit("Goblin", 5, null, 1);
		MonsterTracker.Snapshot s = t.snapshot().get(0);
		assertEquals(5, s.getBiggestHit());
		assertNull(s.getBiggestHitStyle());
		assertTrue(s.getBiggestByStyle().isEmpty());
	}

	@Test
	public void lootStacksAcrossKillsAndSortsByValue()
	{
		MonsterTracker t = new MonsterTracker();
		t.recordKill("Abyssal demon", Arrays.asList(
			new MonsterTracker.Drop(995, "Coins", 500, 1),
			new MonsterTracker.Drop(4151, "Abyssal whip", 1, 1_500_000)), 1);
		t.recordKill("Abyssal demon", Collections.singletonList(
			new MonsterTracker.Drop(995, "Coins", 250, 1)), 2);

		MonsterTracker.Snapshot s = t.snapshot().get(0);
		assertEquals(2, s.getKills());
		assertEquals(1_500_750, s.getLootValue());

		List<MonsterTracker.LootLine> loot = s.getLoot();
		assertEquals("Abyssal whip", loot.get(0).getName());
		assertEquals("Coins", loot.get(1).getName());
		assertEquals(750, loot.get(1).getQuantity());
	}

	@Test
	public void mostRecentMonsterFirst()
	{
		MonsterTracker t = new MonsterTracker();
		t.recordHit("Goblin", 1, CombatStyle.MELEE, 10);
		t.recordHit("Cow", 1, CombatStyle.MELEE, 20);
		assertEquals("Cow", t.snapshot().get(0).getName());
		t.recordHit("Goblin", 1, CombatStyle.MELEE, 30);
		assertEquals("Goblin", t.snapshot().get(0).getName());
	}

	@Test
	public void revisionChangesOnEveryUpdate()
	{
		MonsterTracker t = new MonsterTracker();
		int r0 = t.getRevision();
		t.recordHit("Cow", 1, CombatStyle.MELEE, 1);
		int r1 = t.getRevision();
		t.remove("Cow");
		int r2 = t.getRevision();
		assertTrue(r1 > r0);
		assertTrue(r2 > r1);
		assertTrue(t.snapshot().isEmpty());
	}

	@Test
	public void namelessTargetsAreIgnored()
	{
		MonsterTracker t = new MonsterTracker();
		t.recordHit(null, 10, CombatStyle.MELEE, 1);
		t.recordHit("", 10, CombatStyle.MELEE, 1);
		assertTrue(t.snapshot().isEmpty());
	}
}

package com.combatxptracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Experience;
import org.junit.Test;

public class SkillProgressTest
{
	private static final int WINDOW_SECONDS = 300;

	@Test
	public void xpPerHourFromTwoSamples()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(1_000_000, 0);
		p.recordXp(1_001_000, 60_000, WINDOW_SECONDS);
		// 1,000 xp in one minute = 60,000 xp/hr
		assertEquals(60_000, p.getXpPerHour());
	}

	@Test
	public void noRateWithoutTwoSamples()
	{
		SkillProgress p = new SkillProgress();
		assertEquals(0, p.getXpPerHour());
		p.resetBaseline(500, 0);
		assertEquals(0, p.getXpPerHour());
		assertEquals(-1, p.getEstimatedHoursToGoal(), 0.0);
	}

	@Test
	public void oldSamplesFallOutOfTheWindow()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(0, 0);
		p.recordXp(10_000, 10_000, 30);
		// A burst of 10k at the start; 60s later only this window's gains count.
		p.recordXp(10_100, 60_000, 30);
		p.recordXp(10_200, 70_000, 30);
		// Window is now [60s..70s]: 100 xp in 10 seconds = 36,000 xp/hr
		assertEquals(36_000, p.getXpPerHour());
	}

	/**
	 * Regression test for the 1.3.x bug: progress was measured from the start of the
	 * current level, so the bar dropped to ~0% on every level-up.
	 */
	@Test
	public void progressNeverGoesBackwardsAcrossLevelUps()
	{
		SkillProgress p = new SkillProgress();
		int start = Experience.getXpForLevel(70) + 1_000;
		p.resetBaseline(start, 0);
		p.setGoal(Goal.ofLevel(99), start);

		double previous = p.getProgressToGoal();
		assertEquals(0.0, previous, 1e-9);

		long t = 0;
		for (int xp = start; xp <= Experience.getXpForLevel(80); xp += 25_000)
		{
			t += 1_000;
			p.recordXp(xp, t, WINDOW_SECONDS);
			double now = p.getProgressToGoal();
			assertTrue("progress went backwards at " + xp + " xp", now >= previous);
			previous = now;
		}
		assertTrue(previous > 0.0);
	}

	@Test
	public void progressIsMeasuredFromTheGoalStart()
	{
		int target = Experience.getXpForLevel(99);
		// Halfway between the start and the goal.
		int start = 1_000_000;
		int halfway = start + (target - start) / 2;
		assertEquals(0.5, SkillProgress.progress(halfway, start, target), 1e-6);
		assertEquals(0.0, SkillProgress.progress(start, start, target), 1e-9);
		assertEquals(1.0, SkillProgress.progress(target, start, target), 1e-9);
		assertEquals(1.0, SkillProgress.progress(target + 5, start, target), 1e-9);
	}

	@Test
	public void goalsPast99WorkUpTo200m()
	{
		SkillProgress p = new SkillProgress();
		int xp = 100_000_000;
		p.resetBaseline(xp, 0);
		p.setGoal(Goal.ofXp(200_000_000), xp);
		assertEquals(0.0, p.getProgressToGoal(), 1e-9);
		assertEquals(100_000_000, p.getXpRemainingToGoal());
		// Virtual level, not capped at 99.
		assertEquals(Experience.getLevelForXp(xp), p.getCurrentLevel());
		assertTrue(p.getCurrentLevel() > 99);

		p.recordXp(150_000_000, 3_600_000, 7200);
		assertEquals(0.5, p.getProgressToGoal(), 1e-9);
		// 50M in an hour -> 1 more hour to go
		assertEquals(1.0, p.getEstimatedHoursToGoal(), 1e-9);
	}

	@Test
	public void goalReached()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(Experience.getXpForLevel(98), 0);
		p.setGoal(Goal.ofLevel(99), Experience.getXpForLevel(98));
		assertFalse(p.isGoalReached());
		p.recordXp(Experience.getXpForLevel(99), 1_000, WINDOW_SECONDS);
		assertTrue(p.isGoalReached());
		assertEquals(1.0, p.getProgressToGoal(), 1e-9);
		assertEquals(0, p.getXpRemainingToGoal());
	}

	@Test
	public void unknownStartFallsBackToCurrentLevel()
	{
		// Goals saved by 1.3.x have no start XP until the plugin fills one in.
		int levelStart = Experience.getXpForLevel(50);
		int target = Experience.getXpForLevel(51);
		assertEquals(0.0, SkillProgress.progress(levelStart, -1, target), 1e-9);
	}

	@Test
	public void sessionGainCountsFromFirstBaseline()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(1_000, 0);
		p.recordXp(1_500, 1_000, WINDOW_SECONDS);
		// A relog re-baselines but must not restart the session count.
		p.reset();
		p.resetBaseline(1_500, 5_000);
		p.recordXp(1_800, 6_000, WINDOW_SECONDS);
		assertEquals(800, p.getSessionXpGained());

		p.resetSession();
		assertEquals(0, p.getSessionXpGained());
	}
}

